// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();

    const ownersPageResponsePromise = page.waitForResponse(
        (response) => response.url().includes('/petclinic/api/v2/owners')
    );
    await page.getByRole("link", { name: "Search" }).click();
    const ownersPageResponse = await ownersPageResponsePromise;

    expect(ownersPageResponse.status()).toBe(200);
    const ownersPage = await ownersPageResponse.json();

    expect(ownersPage.page).toBe(0);
    expect(ownersPage.size).toBe(5);
    expect(ownersPage.content.length).toBe(5);
    expect(ownersPage.content[5]).toBeUndefined();
    expect(ownersPage.content[0].firstName).toBe("George");
    expect(ownersPage.content[0].lastName).toBe("Franklin");
    expect(ownersPage.totalElements).toBe(10);
    expect(ownersPage.totalPages).toBe(Math.ceil(ownersPage.totalElements / ownersPage.size));

    await expect(page).toHaveURL(/\/petclinic\/owners$/);
    await expect(page.locator('#ownersTable .ownerFullName').first()).toHaveText('George Franklin');
    await expect(page.locator('#ownersTable .ownerFullName')).toHaveCount(ownersPage.totalElements);
});
